[METTMSEngineDocumentTypeAttribute(METTMSSourceDocumentType::TransferOrderDocument)]
public class METTMSEngineHeaderTransferOrderContract extends METTMSEngineHeaderContract
{
    METInventTransferTableExt inventTransferTableExt;
    CustAccount custAccount;

}

Method.Source:
/// <summary>
/// Initialize the contract variables
/// </summary>
public void init()
{
    inventTransferTableExt = METInventTransferTableExt::findByTransferId(sourceRecord.OrderId);
    headerExtMap = inventTransferTableExt;
}

/// <summary>
/// Gets the extension table buffer
/// </summary>
/// <returns>Header extension record buffer</returns>
public Common getExtensionTable()
{
    Common ret = inventTransferTableExt;

    return ret;
}

/// <summary>
/// Gets the customer account of the order
/// </summary>
/// <returns>Customer account number</returns>
public CustAccount getCustomerAccount()
{
    if(custAccount != '')
    {
        custAccount = METInventLocation::findByInventLocationId(sourceRecord.InventLocationTo).InternalCustomer;
    }

    return custAccount;
}

/// <summary>
/// Gets the route id from header extension table
/// </summary>
/// <returns>Order route id</returns>
public METRoute getRoute()
{
    return inventTransferTableExt.Route;
}

/// <summary>
/// Generates and returns the shipment id
/// </summary>
/// <returns>Shipment id</returns>
public METTMSShipmentID getShipmentID()
{
    if(!shipmentId)
    {
        str shippingDateStr = date2Str
        (this.getShipDate(),
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

        shipmentId = strFmt("@MET:ShipmentStrFmt",
        sourceRecord.InventLocationFrom,
        sourceRecord.InventLocationTo,
        inventTransferTableExt.Route,
        shippingDateStr);
    }

    return super();
}

/// <summary>
/// Route stop id from order extension table buffer
/// </summary>
/// <returns>Route stop id</returns>
public METRouteStopNum getRouteStop()
{
    METRouteStopNum ret = inventTransferTableExt.RouteStopNum;

    return ret;
}

/// <summary>
/// Get success or failure message
/// </summary>
/// <param name = "_shipmentCreated">Is shipment created</param>
/// <returns>Success or failure message</returns>
public SysInfoLogStr showInfo(boolean _shipmentCreated)
{
    SysInfoLogStr msg;

    if (_shipmentCreated)
    {
        msg = strFmt("@MET:TMSEngineSuccessMsgTO", this.parmSourceRecord().OrderId);
    }
    else
    {
        msg = strFmt("@MET:TMSEngineCompletedMsgTO", this.parmSourceRecord().OrderId);
    }

    return msg;
}

/// <summary>
/// Get the destination type, customer or warehouse
/// </summary>
/// <returns>Warehouse or customer</returns>
public METDestinationType getDestinationType()
{
    return METDestinationType::Warehouse;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value.
/// </returns>
public boolean isOrderExcluded()
{
    boolean ret = false;

    ret = (inventTransferTableExt.TransferType == METCrossDockTransferType::None && inventTransferTableExt.IOMSyncCompleted == NoYes::No); 

    return ret;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value.
/// </returns>
public boolean isOrderExcludedTransferType()
{
    return inventTransferTableExt.TransferType == METCrossDockTransferType::None;
}

/// <summary>
/// Gets the order is internal cross dock order or not
/// </summary>
/// <returns>true, if the order is cross dock order otherwise false</returns>
public NoYes isInternalCrossDockOrder()
{
    NoYes ret;

    ret = false;

    return ret;
}

/// <summary>
/// Gets the carrier code of the order
/// </summary>
/// <returns>Carrier code</returns>
public TMSCarrierCode getCarrierCode()
{
    TMSCarrierCode ret;

    if(!carrierCode)
    {
        carrierCode = TMSInventTransferTable::find(sourceRecord.OrderId).CarrierCode;
    }

    ret = super();

    return ret;
}
